import{_ as t,o,c as a,ag as s}from"./chunks/framework.BIas3y6W.js";const p=JSON.parse('{"title":"Building Apps with AI — Syllabus","description":"","frontmatter":{"source":"SYLLABUS.md"},"headers":[],"relativePath":"SYLLABUS.md","filePath":"SYLLABUS.md"}'),r={name:"SYLLABUS.md"};function n(i,e,d,l,h,c){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="building-apps-with-ai--syllabus" tabindex="-1">Building Apps with AI — Syllabus <a class="header-anchor" href="#building-apps-with-ai--syllabus" aria-label="Permalink to &quot;Building Apps with AI — Syllabus&quot;">​</a></h1><p><strong>Build real software with AI, on a $0 budget.</strong> University of Idaho · CS [2xxx] · 3 credits · a 16-week semester · two 75-minute studios a week plus about 6 hours outside class · prerequisite: one programming course in any language.</p><h2 id="course-information" tabindex="-1">Course information <a class="header-anchor" href="#course-information" aria-label="Permalink to &quot;Course information&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td><strong>Course title</strong></td><td>Building Apps with AI</td></tr><tr><td><strong>Course number</strong></td><td>CS [2xxx]: a proposed new lower-division undergraduate course, open to students from any major. The Registrar assigns the number when the University Curriculum Committee approves the course</td></tr><tr><td><strong>Catalog description</strong> (proposed)</td><td>Builds and ships web apps by directing AI tools, and teaches the engineering habits that make AI-written software trustworthy: writing specifications, testing, version control, reading and debugging code, protecting secrets and data, and deploying to the web. Introduces &quot;vibe coding&quot; and its limits. Students complete several deployed web projects using free AI tools. For students from any major who have taken one programming course</td></tr><tr><td><strong>Institution</strong></td><td>University of Idaho</td></tr><tr><td><strong>Credits</strong></td><td>3, which means about <strong>135 hours</strong> of work in all (catalog Regulation D-1)</td></tr><tr><td><strong>Format and length</strong></td><td>In person. <strong>A 16-week semester</strong>: two 75-minute studios a week (<strong>Studio A — Learn &amp; build</strong> and <strong>Studio B — Workshop</strong>) plus about 6 hours of work outside class, so about <strong>8.5 hours a week</strong>. Weeks 1–15 are teaching weeks; week 16 is finals week (<a href="#4-how-the-course-works">section 4</a>)</td></tr><tr><td><strong>Dates</strong></td><td><em>to be added</em></td></tr><tr><td><strong>Meeting times and rooms</strong></td><td>Studio A: <em>to be added</em> · Studio B: <em>to be added</em></td></tr><tr><td><strong>Final exam period</strong></td><td>The <strong>Project Fair</strong>, in the course&#39;s scheduled 2-hour final exam slot in finals week (catalog Regulation H-1-b): <em>to be added</em></td></tr><tr><td><strong>Prerequisites</strong></td><td>One programming course in any language, for example CS 1112 Computational Thinking and Problem Solving, CS 1120 Computer Science I, CS 2120 Practical Python, or another department&#39;s programming course; or equivalent programming experience; or instructor permission</td></tr><tr><td><strong>Instructor</strong></td><td>Boyu Zhang, <em>title to be added</em></td></tr><tr><td><strong>Email and phone</strong></td><td><em>to be added</em> · Response time: <em>to be added</em></td></tr><tr><td><strong>Office</strong></td><td><em>to be added</em></td></tr><tr><td><strong>Office hours</strong></td><td><em>to be added</em></td></tr><tr><td><strong>Canvas</strong></td><td>Canvas, the course&#39;s learning management system (LMS): <em>link to be added</em>. Submissions, grades, feedback and all your personal writing go here</td></tr><tr><td><strong>Course website</strong></td><td><a href="https://boyu-zhang-uoi.github.io/building-apps-with-ai/" target="_blank" rel="noreferrer">boyu-zhang-uoi.github.io/building-apps-with-ai</a> (all course materials)</td></tr><tr><td><strong>Required materials</strong></td><td>No textbook. A laptop with a modern browser and free accounts (<a href="#2-who-this-course-is-for">section 2</a>). Required cost: <strong>$0</strong> (<a href="#10-tools-and-cost">section 10</a>)</td></tr></tbody></table><blockquote><p>Tool names, limits and prices live in <a href="./TOOLS.html">Tool Handout</a>, which carries a date and is re-checked before every cohort. This syllabus deliberately avoids model versions and credit numbers, because they change monthly.</p></blockquote><p><strong>First step:</strong> do the <a href="./setup/#before-studio-1">first-hour quick start</a> before Studio 1 (about 60–90 minutes).</p><hr><h2 id="1-course-description" tabindex="-1">1. Course description <a class="header-anchor" href="#1-course-description" aria-label="Permalink to &quot;1. Course description&quot;">​</a></h2><p>In February 2025 Andrej Karpathy named a new way of making software: describe what you want to an AI, accept what it writes, run it, and keep going on &quot;vibes&quot;. A year later the same people were calling the professional version <em>agentic engineering</em>, and a lot of vibe-coded apps had leaked their users&#39; data.</p><p>This course teaches both halves. You will build and ship five working web projects by directing AI tools, starting in a chat window in week 1 and ending with an AI agent working inside your own repository in weeks 11–16. You will also learn the small set of habits that separate a demo from software you can trust: writing a spec before you prompt, writing the check before the code, working in small steps with git save points, testing, reading and explaining what the AI wrote, keeping secrets secret, and locking down your database.</p><p>You have already taken a programming course, so the course doesn&#39;t teach what a loop or a function is. It teaches what is new to most students: how the web works (HTML, CSS, JavaScript, servers and databases), the terminal, git, and how to direct an AI and check its work.</p><p>Every required tool has a free tier. The course is designed so that when a tool changes its limits (and they will), you switch to a fallback and keep working.</p><h2 id="2-who-this-course-is-for" tabindex="-1">2. Who this course is for <a class="header-anchor" href="#2-who-this-course-is-for" aria-label="Permalink to &quot;2. Who this course is for&quot;">​</a></h2><ul><li><strong>Primary audience:</strong> students from any major (engineering, data science, business, the sciences, the arts and more) who have taken one programming course, usually in Python. You can write a loop and a function. You don&#39;t need to know HTML, CSS, JavaScript, the terminal, git or how the web works: the course teaches them, and the <a href="./setup/python-to-javascript.html">From Python to JavaScript</a> page covers the differences that trip Python programmers up.</li><li><strong>CS students who have completed CS 3383 Software Engineering:</strong> look at the upper-division course <strong><a href="https://boyu-zhang-uoi.github.io/engineering-software-with-ai/" target="_blank" rel="noreferrer">Engineering Software with AI</a></strong> (CS [4xxx]/[5xxx]) instead. It builds on what you already know.</li><li><strong>Under 18, or in the EEA, the UK or Switzerland?</strong> Several free tools are 18+ only or can&#39;t be used to serve European users. <strong>Tell the instructor before the course starts</strong>, so the class can switch to an adjusted stack.</li></ul><p><strong>What you need:</strong> a laptop (Windows, macOS, Linux or ChromeOS) with a modern browser, a personal email address, your phone for two-factor sign-in, and a GitHub account. All coding happens in the browser through GitHub Codespaces, so you don&#39;t have to install anything. A local setup is optional (<a href="./setup/local-setup.html">Optional: set up your own computer</a>). The accounts are listed in <a href="./setup/accounts.html">Accounts</a>.</p><h2 id="3-learning-outcomes" tabindex="-1">3. Learning outcomes <a class="header-anchor" href="#3-learning-outcomes" aria-label="Permalink to &quot;3. Learning outcomes&quot;">​</a></h2><p>By the end of the course you will be able to:</p><ol><li><strong>Direct</strong> AI tools to build working web software, from single-file pages to a deployed full-stack app, using a repeatable workflow (the Safe Loop).</li><li><strong>Specify</strong> what you want before you build it: a one-page spec with user stories and testable acceptance criteria.</li><li><strong>Verify</strong> AI output instead of trusting it: write the check first, run it, test the happy path and edge cases, and read the diff.</li><li><strong>Explain</strong> every part of the code you submit, and debug a failing program by reading its error messages, with the AI switched off.</li><li><strong>Use version control</strong> (git and GitHub) as a safety net: commit, compare, revert, branch and review through pull requests.</li><li><strong>Build safely:</strong> protect privacy and secrets, keep API keys on the server, enforce database access rules, check dependencies, and contain AI agents.</li><li><strong>Ship</strong> projects to the public web and present them clearly.</li><li><strong>Adapt</strong> when tools change: choose between chat assistants, app builders, editor agents and terminal agents, and switch to a fallback without losing work.</li></ol><h3 id="how-each-outcome-is-assessed" tabindex="-1">How each outcome is assessed <a class="header-anchor" href="#how-each-outcome-is-assessed" aria-label="Permalink to &quot;How each outcome is assessed&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Outcome</th><th>Where you show it</th><th>What the grader looks for</th></tr></thead><tbody><tr><td>1. Direct</td><td>Weekly labs and homework; <code>PROMPTS.md</code></td><td>The &quot;Save points and log&quot; row of the <a href="./assessment/rubrics.html#weekly-labs-and-homework">weekly rubric</a>: small commits and an honest prompt log</td></tr><tr><td>2. Specify</td><td><code>SPEC.md</code> in <a href="./assessment/rubrics.html#project-1">Project 1</a> and the <a href="./assessment/rubrics.html#capstone">capstone</a>; the week 5 peer spec review</td><td>The &quot;Spec&quot; rows: checkable WHEN … THE APP SHALL … criteria, edge cases, a logged Goldfish test</td></tr><tr><td>3. Verify</td><td><code>TESTS.md</code> and automated tests</td><td>The &quot;Tests&quot; rows: edge cases with dated results; at least three automated tests of Project 1&#39;s logic; in the capstone, tests written before the code</td></tr><tr><td>4. Explain</td><td><a href="./assessment/oral-walkthroughs.html">Oral walkthroughs</a> 1–3; exit tickets (practice)</td><td>The Explain, Modify and Debug areas of each walkthrough, and the <a href="#six-skills-you-must-be-able-to-show-without-ai">six skills</a></td></tr><tr><td>5. Version control</td><td>Walkthrough &quot;Process&quot; area; capstone &quot;Process&quot; row</td><td>Reverting a commit with the AI off; small commits; features merged through pull requests</td></tr><tr><td>6. Build safely</td><td>Capstone security checklist; the micro-app&#39;s &quot;Key stays on the server&quot; row</td><td>Real evidence: secret-scan output, RLS on with policies, your own attack failing</td></tr><tr><td>7. Ship</td><td>Deployment rows; the capstone README and demo video; the Project Fair</td><td>A production URL that works in a private window, a clear README and a 2–3 minute demo</td></tr><tr><td>8. Adapt</td><td>The micro-app&#39;s &quot;Provider swap&quot; row; the capstone README&#39;s tools line</td><td>Two providers run by changing configuration only; the tools and any fallback you used</td></tr></tbody></table><p><strong>Example: how outcome 4 is assessed.</strong> In <a href="./assessment/oral-walkthroughs.html#walkthrough-1-week-8">walkthrough 1</a> (week 8), with the AI off, you explain a function from your Project 1, find the failing line after the examiner breaks something, fix it, and revert a commit. The examiner scores four areas (Explain, Modify, Debug, Process) from 0 to 4 each (<a href="./assessment/oral-walkthroughs.html#scoring">scoring</a>), and records which of the six without-AI skills you showed.</p><h2 id="4-how-the-course-works" tabindex="-1">4. How the course works <a class="header-anchor" href="#4-how-the-course-works" aria-label="Permalink to &quot;4. How the course works&quot;">​</a></h2><h3 id="two-studios-a-week" tabindex="-1">Two studios a week <a class="header-anchor" href="#two-studios-a-week" aria-label="Permalink to &quot;Two studios a week&quot;">​</a></h3><p>Weeks 1–15 each have two 75-minute studios a few days apart (for example Tuesday and Thursday), plus about 6 hours of work outside class. Week 16 is finals week: there are no regular studios, and the <a href="./weeks/16-project-fair/project-fair.html">Project Fair</a> runs in the course&#39;s scheduled 2-hour final exam slot (Regulation H-1-b). Each week&#39;s <code>README.md</code> opens with a <strong>This week at a glance</strong> table: what to do before Studio A, what each studio covers, what&#39;s due, the AI rules and the minimum you need to keep up.</p><table tabindex="0"><thead><tr><th>Block</th><th>Time</th><th>What happens</th></tr></thead><tbody><tr><td><strong>Studio A — Learn &amp; build</strong></td><td>75 min</td><td>Recap of last week&#39;s most-missed exit-ticket question (5 min) · concept talk (15 minutes at most) · live demo (10 minutes at most) · lab, core parts (about 40 min) · checkpoint share (5 min)</td></tr><tr><td><strong>Studio B — Workshop</strong></td><td>75 min</td><td>Show and tell (5 min) · lab continued, or a mini-lesson and practice on the week&#39;s second skill (about 40 min) · project work time, with oral-walkthrough slots in weeks 8, 12 and 14 and catch-up help (about 15 min) · debrief question (5 min) · exit ticket (10 min, 🔴 AI off)</td></tr><tr><td><strong>Outside class</strong></td><td>about 6 h</td><td>Prep before Studio A (30 minutes at most: the week&#39;s README and at most one short reading) · homework core (about 3 hours) · project build time (about 2 hours) · <code>PROMPTS.md</code> and your weekly reflection on Canvas (about 30 minutes)</td></tr></tbody></table><p>Some weeks move minutes between these blocks, but every studio stays 75 minutes, and the timed and AI-off activities (the Game in an Hour in week 3, the Debug Clinic in week 7, Be the Agent in week 11, the RLS Attack Lab in week 13 and the AI-off maintenance task in week 14) always fit whole inside one studio.</p><ul><li><strong>Due dates:</strong> homework is <strong>due before next week&#39;s Studio A</strong> (by default, 11:59 pm the night before). Canvas shows the exact time. Now and then a task that needs only Studio A&#39;s skills is due before Studio B; the week&#39;s page says so.</li><li><strong>Core and stretch.</strong> Every lab part is marked <strong>Core</strong> or <strong>If time</strong>. Homework has a <strong>core</strong> tier (required) and a <strong>stretch</strong> tier (optional, never graded). Every homework ends with a <strong>Minimum to keep up</strong> box: the one thing you must have working before the next week.</li><li><strong>Exit tickets</strong> are short questions with the AI off, once a week in weeks 1–14, normally at the end of Studio B (at the end of Studio A when a timed activity fills Studio B). From week 3, one question each week asks about a decision or function in your project from <strong>two weeks earlier</strong>, because remembering it later is what counts. They&#39;re graded on completion, not on correctness.</li><li><strong>Oral walkthroughs</strong> (10 minutes each, 🔴 AI off) run in <strong>weeks 8, 12 and 14</strong>, during both studios&#39; project time and in office-hour slots that week. Slots outside class time are scheduled at least two weeks ahead and announced in the first week; I cancel equivalent studio time to make room for them, and anyone with a conflict gets another time (catalog Regulation O-9-c). If you&#39;re not in a slot, you keep working on the lab.</li><li><strong>Week 15 has no exit ticket and no walkthrough.</strong> University Regulation H-1-a says: &quot;No quizzes or exams may be given in lecture-recitation periods during the week before finals week.&quot; So week 15 is for finishing your capstone, and week 16&#39;s Project Fair takes the place of a final exam.</li></ul><h3 id="the-safe-loop" tabindex="-1">The Safe Loop <a class="header-anchor" href="#the-safe-loop" aria-label="Permalink to &quot;The Safe Loop&quot;">​</a></h3><p>Every lab from week 3 onward uses the same six-step loop (<a href="./resources/safe-loop.html">The Safe Loop</a>):</p><table tabindex="0"><thead><tr><th>#</th><th>Step</th><th>What you do</th></tr></thead><tbody><tr><td>1</td><td><strong>Describe</strong></td><td>State the goal, context, constraints and &quot;done when&quot;. <strong>Check first:</strong> write the &quot;done when&quot; check before you ask for the code, in a separate prompt (from week 6, an automated test wherever the logic allows it)</td></tr><tr><td>2</td><td><strong>Plan</strong></td><td>Ask the AI for a plan. Edit it before any code is written</td></tr><tr><td>3</td><td><strong>Step</strong></td><td>Build one small piece at a time</td></tr><tr><td>4</td><td><strong>Test</strong></td><td>Run it: your check, the normal case and at least one edge case, yourself</td></tr><tr><td>5</td><td><strong>Read</strong></td><td>Read the diff. Keep only what you can explain. <strong>Teach back:</strong> before you commit AI-written code, write 2–3 sentences in <code>PROMPTS.md</code> saying what changed and why</td></tr><tr><td>6</td><td><strong>Commit</strong></td><td>Make a git save point with a clear message. Commits made with AI help end with an <code>Assisted-by: [tool]</code> line (taught in week 3, required from week 11)</td></tr></tbody></table><p><strong>Two-strikes rule:</strong> if two attempts to fix the same problem fail, stop. Start a fresh chat and rewrite your prompt with what you learned.</p><p><strong>Why check first and teach back?</strong> Tests an AI writes <em>after</em> faulty code tend to agree with the faults (<a href="https://arxiv.org/abs/2607.05139" target="_blank" rel="noreferrer">Konstantinou et al.</a>), and students who had to explain AI code before adding it failed an AI-off maintenance task far less often than students who didn&#39;t (<a href="https://arxiv.org/abs/2602.20206" target="_blank" rel="noreferrer">Sankaranarayanan</a>). Being able to program already doesn&#39;t change this: experienced developers in one study were 19% slower with AI while believing they were faster (<a href="https://metr.org/blog/2025-07-10-early-2025-ai-experienced-os-dev-study/" target="_blank" rel="noreferrer">METR</a>).</p><h3 id="three-habits-for-talking-to-an-ai" tabindex="-1">Three habits for talking to an AI <a class="header-anchor" href="#three-habits-for-talking-to-an-ai" aria-label="Permalink to &quot;Three habits for talking to an AI&quot;">​</a></h3><p>Taught in week 2 and used all course:</p><ol><li><strong>Ask the AI to ask you questions first,</strong> before it builds anything.</li><li><strong>Show, don&#39;t describe:</strong> give it a picture, a sketch or a reference instead of a long description.</li><li><strong>Say what already works</strong> before you ask for a change, so it doesn&#39;t break it.</li></ol><p>The <strong>Goldfish test</strong> (weeks 5 and 12) checks your documents the same way: paste only your <code>SPEC.md</code> (or <code>AGENTS.md</code>) into a fresh chat. If it can&#39;t understand or build from the document alone, without asking you, the document needs revising.</p><h3 id="the-ladder-of-tools" tabindex="-1">The ladder of tools <a class="header-anchor" href="#the-ladder-of-tools" aria-label="Permalink to &quot;The ladder of tools&quot;">​</a></h3><p>The course climbs from the most guided tools to the most autonomous. Each rung is introduced only after the habits it needs.</p><table tabindex="0"><thead><tr><th>Weeks</th><th>Tool</th><th>Who does what</th></tr></thead><tbody><tr><td>1–4</td><td>Chat assistant with live preview</td><td>You copy, paste and commit</td></tr><tr><td>6</td><td>Browser app builders</td><td>The AI builds a whole app from your spec</td></tr><tr><td>6–8</td><td>Editor with an AI assistant</td><td>You read, debug and write; the AI advises</td></tr><tr><td>9–10</td><td>Editor, AI and your own server</td><td>Secrets, APIs and deployment</td></tr><tr><td>11–16</td><td>AI agent in your repository</td><td>The AI edits files and runs commands; you supervise, with approvals on</td></tr></tbody></table><p>Week 5 is spec week: you write, and a chat assistant only critiques and runs the Goldfish test.</p><h2 id="5-weekly-schedule" tabindex="-1">5. Weekly schedule <a class="header-anchor" href="#5-weekly-schedule" aria-label="Permalink to &quot;5. Weekly schedule&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Week</th><th>Title</th><th>Big idea</th><th>You build</th><th>Tools (primary)</th></tr></thead><tbody><tr><td>0</td><td><a href="./setup/">Pre-work</a></td><td>Accounts, privacy, a first win</td><td>A one-line web page in a chat preview; a tested Codespace</td><td>GitHub, Google account</td></tr><tr><td>1</td><td><a href="./weeks/01-hello-vibe-coding/">Hello, Vibe Coding</a></td><td>What vibe coding is, and how an LLM writes code</td><td>A personal page built in a chat preview, explained, and changed by hand</td><td>Chat assistant with preview</td></tr><tr><td>2</td><td><a href="./weeks/02-ship-your-page/">Ship Your Page</a></td><td>Live on the web, accessible, and yours</td><td>Your home page, live on the web; your personal AI-use rules</td><td>Chat assistant with preview · GitHub Pages</td></tr><tr><td>3</td><td><a href="./weeks/03-prompting-and-save-points/">Prompting &amp; Save Points</a></td><td>Prompts as direction; commits as save points</td><td>A browser game in one hour</td><td>Chat assistant · github.dev</td></tr><tr><td>4</td><td><a href="./weeks/04-undo-compare-explain/">Undo, Compare, Explain</a></td><td>Save points make experiments safe; tests check for you</td><td>A rollback, a two-model comparison, a prompt makeover, your first automated test</td><td>Two chat assistants · github.dev · Codespaces</td></tr><tr><td>5</td><td><a href="./weeks/05-spec-first/">Spec First</a></td><td>A spec is the prompt for the whole project</td><td>Your Project 1 spec, peer-reviewed and Goldfish-tested</td><td>Chat assistant (critique only)</td></tr><tr><td>6</td><td><a href="./weeks/06-spec-to-app/">From Spec to App</a></td><td>Builders get you most of the way; checks get you the rest</td><td>Project 1 v1 from your own spec, checked first with a test</td><td>App builders (jigsaw bake-off) · Codespaces</td></tr><tr><td>7</td><td><a href="./weeks/07-read-and-debug/">Read It, Debug It</a></td><td>You must be able to read and fix what the AI wrote</td><td>Debug Clinic; edge-case tests for Project 1</td><td>Codespaces · VS Code · Copilot (Ask mode)</td></tr><tr><td>8</td><td><a href="./weeks/08-own-it/">Own It</a></td><td>If you can&#39;t explain it, you didn&#39;t build it</td><td>A function you write yourself; tests of Project 1&#39;s logic; Project 1 final</td><td>Codespaces · VS Code · Copilot (Ask mode)</td></tr><tr><td>9</td><td><a href="./weeks/09-apis-and-secrets/">APIs &amp; Secrets</a></td><td>The browser is public; secrets live on the server</td><td>An AI-powered micro-app, running in your Codespace</td><td>Free LLM API · Codespaces</td></tr><tr><td>10</td><td><a href="./weeks/10-servers-and-deployment/">Servers &amp; Deployment</a></td><td>Deployed, swappable, and the key still secret</td><td>The micro-app, deployed, with your own validation tests; your capstone pitch</td><td>Free LLM API · Vercel</td></tr><tr><td>11</td><td><a href="./weeks/11-agents/">How Agents Work</a></td><td>An agent is an LLM in a loop with tools</td><td>Capstone kickoff: your first agent-built, tested feature</td><td>Copilot agent mode and CLI in a Codespace</td></tr><tr><td>12</td><td><a href="./weeks/12-pull-requests/">Pull Requests &amp; Agent Code</a></td><td>Agent code gets reviewed before it&#39;s merged</td><td>Features merged through pull requests; Milestone 1</td><td>Copilot agent mode · GitHub pull requests</td></tr><tr><td>13</td><td><a href="./weeks/13-data-and-access/">Data &amp; Access Rules</a></td><td>Public key + missing access rules = public database</td><td>RLS Attack Lab; your capstone&#39;s database</td><td>Supabase</td></tr><tr><td>14</td><td><a href="./weeks/14-security-and-review/">Security &amp; Review</a></td><td>Treat outside input, packages and content as untrusted</td><td>A security sweep, a pull-request review and the AI-off maintenance task; Milestone 2</td><td>Secret and dependency scanners</td></tr><tr><td>15</td><td><a href="./weeks/15-ship-it/">Ship It</a></td><td>Done means deployed, documented and explainable</td><td>Capstone polish and your demo video</td><td>Everything</td></tr><tr><td>16</td><td><a href="./weeks/16-project-fair/">Project Fair</a> (finals week)</td><td>Show what you built, and how you know it works</td><td>The Project Fair; your final submission</td><td>Everything</td></tr></tbody></table><h3 id="week-by-week-detail" tabindex="-1">Week-by-week detail <a class="header-anchor" href="#week-by-week-detail" aria-label="Permalink to &quot;Week-by-week detail&quot;">​</a></h3><p><strong>Week 0 — Pre-work.</strong> <strong>Before Studio 1</strong> (about 60–90 minutes, <a href="./setup/#before-studio-1">quick start</a>): create your accounts, change the privacy settings, open a test Codespace, switch on GitHub Copilot, and get a first win: a one-line web page running in a chat assistant&#39;s preview. <strong>During week 1</strong> (<a href="./setup/#during-week-1">details</a>): sign the <a href="./setup/safety-contract.html">safety contract</a> on Canvas, take the pre-course <a href="./assessment/self-assessment.html">self-assessment</a> on Canvas, and apply for GitHub Education (verification can take several days, so start early). <strong>From Python to JavaScript</strong> (<a href="./setup/python-to-javascript.html">bridge page</a>): the JavaScript differences that trip Python programmers up, such as <code>===</code> versus <code>==</code>, <code>const</code> and <code>let</code>, braces instead of indentation, and <code>null</code> and <code>undefined</code>. Skim it in week 1 and keep it open.</p><p><strong>Week 1 — Hello, Vibe Coding.</strong> What Karpathy meant, and why the field moved on. A mental model of LLMs: next-token prediction, context, non-determinism, confident mistakes. Privacy and the safety contract. <em>In the studios:</em> build a single-file personal page in a chat assistant with live preview; ask the AI to explain it section by section; change its HTML, CSS and JavaScript by hand (🔴 AI off); exit ticket. <em>Outside class:</em> finish the page, with one small feature you write entirely by hand (🔴 AI off); keep a note of the prompts that mattered and your hand changes; start the <strong>AI fluency pre-work</strong>; the week 0 tasks; reflection on Canvas. <em>Understanding check:</em> explain three parts of your page in plain English.</p><p><strong>Week 2 — Ship Your Page.</strong> Publishing: repositories, GitHub Pages, and what &quot;public&quot; means for your files and their history. <em>In the studios:</em> publish your page on GitHub Pages; the <strong>three habits</strong> card; check your page&#39;s accessibility and fix what it finds; write your <strong>personal AI-use rules</strong>, version 1 (🔴 AI off, on Canvas); start <code>PROMPTS.md</code>; exit ticket. <em>Outside class:</em> improve the page using the three habits; <code>PROMPTS.md</code> (five entries); finish the <strong>AI fluency pre-work</strong>: Anthropic&#39;s free <a href="https://anthropic.skilljar.com/ai-fluency-framework-foundations" target="_blank" rel="noreferrer">AI Fluency: Framework &amp; Foundations</a> course (a free sign-up; about 3 hours) or an equivalent your instructor names, with a short AI-free response on Canvas; reflection on Canvas. <em>Understanding check:</em> who can see your page, its files and its history?</p><p><strong>Week 3 — Prompting &amp; Save Points.</strong> Prompt anatomy (Goal · Context · Constraints · Done when). Why one giant prompt produces code you can&#39;t change later. Git basics: commit, history, diff, revert, and the <code>Assisted-by:</code> line. <em>In the studios:</em> practice the save-point workflow once, slowly (a four-part prompt, the diff, a commit with an <code>Assisted-by:</code> line, your history); exit ticket; then the timed <strong>Game in an Hour</strong>, built from a five-step plan with one commit per working step (graded on effort and save points, not on finishing), and a play-test swap. <em>Outside class:</em> finish the game; read Simon Willison&#39;s <a href="https://simonwillison.net/2025/Mar/19/vibe-coding/" target="_blank" rel="noreferrer">&quot;Not all AI-assisted programming is vibe coding&quot;</a>; reflection. <em>Understanding check:</em> rewrite a weak prompt in four parts.</p><p><strong>Week 4 — Undo, Compare, Explain.</strong> Save points make experiments safe, and an automated test checks your code for you. <em>In the studios:</em> a deliberate break-and-restore rollback; a two-model comparison; a peer explanation swap (🔴 AI off); your <strong>first automated test</strong>: a function from your game checked with <code>node --test</code>; the <strong>prompt makeover</strong> workshop; exit ticket. <em>Outside class:</em> add one more feature to your game in at least three save points, with a check written before each step; a restore drill; your game using the tested function in <code>game/logic.js</code>, with a test of your own passing; finish your prompt makeover (🔴 AI off for the rewrites); reflection. <em>Understanding check:</em> explain one function in a classmate&#39;s game.</p><p><strong>Week 5 — Spec First.</strong> The one-page spec: problem, user, user stories, acceptance criteria in WHEN … THE APP SHALL … form, out-of-scope list, wireframe. Edge cases, and why AI-built apps miss them (the &quot;70% problem&quot;). <em>In the studios:</em> write the <code>SPEC.md</code> for Project 1 (🔴 AI off for the first draft); a <strong>peer spec review</strong> (written up on Canvas); the <strong>Goldfish test</strong> of your spec, then revise it; exit ticket. <em>Outside class:</em> revise your spec; <code>TESTS.md</code> with a manual test for every MUST criterion and a plan for your logic; your first automated test for Project 1, written before its code, so it fails for now (check first); your written spec review on Canvas; reflection. <em>Understanding check:</em> turn a vague requirement into a testable criterion.</p><p><strong>Week 6 — From Spec to App.</strong> Browser app builders, what they generate, lock-in and credit budgets. Your app&#39;s rules as pure functions in their own module. <em>In the studios:</em> the builder bake-off as a <strong>jigsaw</strong>: each student runs one builder on their own spec and scores it, then pairs compare scorecards; start Project 1 in a Codespace in Safe Loop order, <strong>checking first</strong> with an automated test where the logic allows it, and previewing every change <strong>before</strong> you commit it (if the page goes blank, open the Console); exit ticket. <em>Outside class:</em> Project 1 v1 live, with at least half of its MUST criteria working and at least one automated test passing; an acceptance table in the README. Your bake-off Verdict (🔴 AI off, on Canvas) is this week&#39;s reflection. <em>Understanding check:</em> which acceptance criteria fail, and why?</p><p><strong>Week 7 — Read It, Debug It.</strong> Anatomy of a web app (structure, style, behavior, state, storage). Browser DevTools, error messages and the scientific method of debugging. <em>In the studios:</em> map your own Project 1 and find planted errors in it with DevTools (an error drill, 🔴 AI off); exit ticket; then the <strong>Debug Clinic</strong>: planted bugs, about an hour with the AI off (🟡 hint-only tutor mode after 10 minutes stuck on one bug), then a debrief. <em>Outside class:</em> check your own Project 1 for the clinic&#39;s five bugs (🔴 AI off); <code>TESTS.md</code> with at least three edge cases; fix what your acceptance table says fails; reflection. <em>Understanding check:</em> find the failing line from an error message.</p><p><strong>Week 8 — Own It.</strong> You own the code you can explain, change and test. <em>In the studios:</em> practice <code>git log</code>, <code>git diff</code> and <code>git revert</code> (🔴 AI off), then write tests for Project 1&#39;s logic while <strong>oral walkthrough 1</strong> slots begin; &quot;<strong>You write it</strong>&quot;: write a function yourself from a short spec, test first (a code skeleton with blanks is a hint if you need one, not the starting point); exit ticket. <em>Outside class:</em> Project 1 final, with at least three automated tests of its pure logic passing with <code>node --test</code>; <code>TESTS.md</code> complete; the mid-course survey; reflection. <strong>Project 1 due.</strong></p><p><strong>Week 9 — APIs &amp; Secrets.</strong> Requests, responses, JSON and APIs. Client versus server: anything sent to the browser is public. API keys, environment variables, <code>.gitignore</code>, free-tier rate limits, and why a public endpoint that spends your key needs limits. Not every key is a secret: some are public by design and safe only with access rules. <em>In the studios:</em> trace one request through the starter AI micro-app yourself; a free LLM API key kept in <code>.env</code>; run it in your Codespace; make it your own (its job and its page); exit ticket. <em>Outside class:</em> your app&#39;s own job, page and input limit, with each error tried on purpose; a first draft of your capstone pitch; reflection.</p><p><strong>Week 10 — Servers &amp; Deployment.</strong> A production URL, a provider you can swap, and proof that the key stays secret. <em>In the studios:</em> deploy to Vercel and check the production URL; the provider-swap drill (change configuration only); prove the key is secret (DevTools, and a secret scan that also checks your git history); a mini-lesson on <strong>external public APIs</strong> (a server route that calls a public API needing no key); exit ticket. <em>Outside class:</em> micro-app live; a &quot;Where the key lives and who can read it&quot; README section (🔴 AI off; it takes the place of this week&#39;s reflection); at least two validation tests that you write yourself; a hidden-costs checklist; your capstone pitch. Rewriting the rate-limit message is stretch. <strong>Micro-app due; capstone pitch due 72 hours before week 11 Studio A.</strong></p><p><strong>Week 11 — How Agents Work.</strong> An agent is an LLM in a loop with tools. Context as working memory, plan-first prompting, approval modes and sandboxes, and how agents fail (fake success, deleted files, loops). <code>AGENTS.md</code> is advice, not enforcement: what actually protects you is the Codespace, approval prompts, narrowly scoped keys, spending caps and database rules. Approvals stay on; never use autopilot or skip-permissions modes. <em>In the studios:</em> <strong>Be the Agent</strong>; open your capstone repo (created from the starter <strong>before</strong> class); write <code>SPEC.md</code> for today&#39;s one criterion and an <code>AGENTS.md</code> with a <strong>Scope</strong> section; build your first feature with an agent, checking first and teaching back; exit ticket. Optional, if you program comfortably: read (don&#39;t write) a minimal agent loop. <em>Outside class:</em> finish your first feature on its own branch (not merged yet); a trace of your agent&#39;s run (🔴 AI off); complete <code>SPEC.md</code>; deploy early; agent log in <code>PROMPTS.md</code>; reflection.</p><p><strong>Week 12 — Pull Requests &amp; Agent Code.</strong> Branches and pull requests, and reading agent-written code before you trust it. <em>In the studios:</em> a mini-lesson on <strong>branches and pull requests</strong> (add one test by hand, then open a pull request, review it yourself and merge it); find a planted bug in agent-written code (🔴 AI off); <strong>feature clinic</strong> stations, where you pick what your capstone needs: a simple chart, or an external API; <strong>oral walkthrough 2</strong> slots; exit ticket. <em>Outside class:</em> the Goldfish test of your <code>SPEC.md</code>; the <strong><code>AGENTS.md</code> trial</strong> (two small tasks: did the agent follow the file? make one change); one more feature as a pull request with a test; reflection. <strong>Milestone 1</strong> (<a href="./projects/capstone.html#milestones">milestones</a>).</p><p><strong>Week 13 — Data &amp; Access Rules.</strong> Authentication versus authorization; row-level security (RLS); publishable versus secret keys; database permissions (&quot;grants&quot;) always together with RLS. 2026 case studies: thousands of databases with publicly readable tables, and a platform that let anyone read other users&#39; projects (<a href="./resources/case-studies.html">case studies</a>). <em>In the studios:</em> the <strong>RLS Attack Lab</strong>, using the attack page hosted on the course website; a worked example of connecting your app to Supabase (the project URL and publishable key in <code>public/config.js</code>, grants and RLS policies), then an attack on your own table; connect one feature with the agent; exit ticket. <em>Outside class:</em> your second feature type working at the production URL, merged through a pull request (Supabase with RLS and <code>supabase/policies.sql</code>, or another feature type); section 3 of <code>SECURITY_CHECKLIST.md</code> with evidence; reflection. From this week to the Fair, open your capstone database at least once a week: free databases pause when nobody uses them.</p><p><strong>Week 14 — Security &amp; Review.</strong> Cross-site scripting; secrets in old commits; slopsquatting; prompt injection and the &quot;lethal trifecta&quot;. 2026 case studies: an agent that deleted a production database and its backups, agents that published private screenshots, and malware that hunts for AI keys (<a href="./resources/case-studies.html">case studies</a>). <em>In the studios:</em> a 7-minute prompt-injection demonstration by the instructor; a security sweep (secret scan including history, <code>npm audit</code>, a package check, an XSS test); a one-paragraph threat model of one feature; exit ticket; then an <strong>AI-off maintenance task</strong> on your own capstone (30 minutes, 🔴 AI off) and <strong>peer review as a pull-request review</strong>, plus your written review on Canvas (🔴 AI off), then compared with an AI&#39;s review. <strong>Oral walkthrough 3</strong> slots run alongside. <em>Outside class:</em> <code>SECURITY_CHECKLIST.md</code> with evidence, and its threat model; respond to your review; the <strong>handoff test</strong> (a partner tries a change using only your README and <code>AGENTS.md</code>); reflection. <strong>Milestone 2.</strong></p><p><strong>Week 15 — Ship It.</strong> Definition of done, polish, accessibility basics, telling the story of a project, and where the field is going. <em>In the studios:</em> polish sprint (accessibility; empty, loading and error states; a README with an honest <strong>Known issues</strong> section); a final security pass; record a 2–3 minute demo video; rehearse your Project Fair pitch. No exit ticket and no walkthrough (Regulation H-1-a). <em>Outside class:</em> finish the polish checklist and bring every document up to date; link your demo video; reflection. Due before the Project Fair.</p><p><strong>Week 16 — Project Fair (finals week).</strong> No regular studios. The <strong>Project Fair</strong> runs in the course&#39;s scheduled 2-hour final exam slot (Regulation H-1-b): you demo your capstone and try your classmates&#39; apps. At the Fair: the post-course self-assessment (🔴 AI off, on Canvas) and the course retrospective. Taking part counts like a studio, with a make-up for absences under Regulations M-1 and M-3. <strong>Final submission:</strong> the production URL and a screenshot, a <code>v1.0</code> release and the demo video are due at the start of the Project Fair; your revised personal AI-use rules and your final reflection (🔴 AI off, on Canvas) are due by 11:59 pm on the last day of finals week.</p><h2 id="6-projects" tabindex="-1">6. Projects <a class="header-anchor" href="#6-projects" aria-label="Permalink to &quot;6. Projects&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Project</th><th>Weeks</th><th>What it is</th><th>Where it lives</th></tr></thead><tbody><tr><td>Home page</td><td>1–4</td><td>A personal page that becomes your portfolio (live by the end of week 2), plus a game in <code>/game/</code> (weeks 3–4)</td><td><code>[username].github.io</code> on GitHub Pages</td></tr><tr><td>Project 1: A Tool I&#39;d Actually Use</td><td>5–8</td><td>A multi-feature, single-user web tool built from your spec, saving data in the browser, with at least three automated tests of its logic</td><td>Its own repo, on GitHub Pages</td></tr><tr><td>AI micro-app</td><td>9–10</td><td>A small app that calls an LLM from a server route</td><td>Its own repo, on Vercel</td></tr><tr><td>Capstone</td><td>11–16</td><td>A deployed full-stack web app of your choice, built with an agent, with at least two of four feature types (pairs: three)</td><td>Its own repo, on Vercel (+ Supabase if it stores shared data)</td></tr></tbody></table><p>Full briefs: <a href="./projects/">projects/</a>. Capstone dates are in one place: the <a href="./projects/capstone.html#milestones">capstone milestones</a>. Every project repository contains a <strong><code>PROMPTS.md</code></strong> log of how you used AI.</p><p><strong>Rules for every project:</strong> no real payments; no real personal data about other people; nothing you would miss if an AI agent deleted it.</p><h2 id="7-assessment" tabindex="-1">7. Assessment <a class="header-anchor" href="#7-assessment" aria-label="Permalink to &quot;7. Assessment&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>Weight</th><th>How it is graded</th></tr></thead><tbody><tr><td>Weekly labs and homework</td><td>20%</td><td>Weeks 1–15: effort and completion of the core tier (<a href="./assessment/rubrics.html#weekly-labs-and-homework">rubric</a>). Weeks 9 and 10 are graded together with the <a href="./assessment/rubrics.html#ai-micro-app">AI micro-app rubric</a></td></tr><tr><td>In-class builds, exit tickets and participation</td><td>15%</td><td>30 studios (two a week, weeks 1–15) and the Project Fair: lab work, peer explanation, checkpoints and exit tickets (<a href="./assessment/rubrics.html#in-class-work-and-participation">rubric</a>)</td></tr><tr><td>Project 1</td><td>10%</td><td><a href="./assessment/rubrics.html#project-1">Project 1 rubric</a></td></tr><tr><td>Capstone</td><td>30%</td><td>Spec quality, tests including edge cases, security, deployment and prompt log. A working demo is required but not sufficient (<a href="./assessment/rubrics.html#capstone">capstone rubric</a>)</td></tr><tr><td>Oral walkthroughs (weeks 8, 12, 14)</td><td>15%</td><td>10-minute conversations with the AI off: explain your code, change it live, find a planted bug (<a href="./assessment/oral-walkthroughs.html">protocol</a>; <a href="./assessment/oral-walkthroughs.html#what-to-expect">what to expect</a>)</td></tr><tr><td>AI-free reflections and peer reviews</td><td>10%</td><td>Your own writing, anchored in specific moments, submitted on Canvas (<a href="./assessment/rubrics.html#reflections-and-peer-reviews">rubric</a>)</td></tr></tbody></table><p><strong>The <a href="./assessment/">assessment guide</a> is part of this syllabus.</strong> It explains how points become your grade, the drops (your lowest two weekly scores, your lowest four in-class scores and your lowest two weekly reflections), retakes, grace tokens, late work, make-ups, pairs and regrades. I go through it in the first studio.</p><p><strong>Why there&#39;s nothing exam-like in week 15:</strong> University Regulation H-1-a doesn&#39;t allow quizzes or exams in class during the week before finals week. So the last walkthrough is in week 14, the last exit ticket is in week 14, and the Project Fair uses the course&#39;s final exam slot in week 16.</p><p><strong>What&#39;s graded on effort, not correctness:</strong> weekly labs, timed builds such as the Game in an Hour, and exit tickets. A lab that didn&#39;t work, with a clear record of the error and what you tried, can still earn full marks.</p><h3 id="letter-grades" tabindex="-1">Letter grades <a class="header-anchor" href="#letter-grades" aria-label="Permalink to &quot;Letter grades&quot;">​</a></h3><p>The University of Idaho uses letter grades without plus or minus.</p><table tabindex="0"><thead><tr><th>Grade</th><th>Course percentage</th></tr></thead><tbody><tr><td><strong>A</strong></td><td>90–100</td></tr><tr><td><strong>B</strong></td><td>80–89</td></tr><tr><td><strong>C</strong></td><td>70–79</td></tr><tr><td><strong>D</strong></td><td>60–69</td></tr><tr><td><strong>F</strong></td><td>below 60</td></tr></tbody></table><p>To earn a C or higher you must also have a capstone that works at its production URL, have taken all three oral walkthroughs, and have shown each of the six skills below at least once (<a href="./assessment/#letter-grades">details</a>).</p><h3 id="six-skills-you-must-be-able-to-show-without-ai" tabindex="-1">Six skills you must be able to show without AI <a class="header-anchor" href="#six-skills-you-must-be-able-to-show-without-ai" aria-label="Permalink to &quot;Six skills you must be able to show without AI&quot;">​</a></h3><p>These are checked in the oral walkthroughs, and practiced in the exit tickets (<a href="./resources/without-ai-skills.html">Six Skills You Must Show Without AI</a>). Each needs to be shown only once, and you get several chances.</p><ol><li>Read an error message and find the failing line.</li><li>Explain any function you committed.</li><li>Write an acceptance criterion and a test for it.</li><li>Revert a bad commit.</li><li>Spot a committed secret.</li><li>Say where authorization is enforced in your app.</li></ol><h3 id="late-work" tabindex="-1">Late work <a class="header-anchor" href="#late-work" aria-label="Permalink to &quot;Late work&quot;">​</a></h3><p>You have <strong>two grace tokens</strong>, each extending one deadline by 48 hours with no reason needed. After that, late work loses 10% of its points per day for up to three days. Tokens can&#39;t be used for live events (studios, exit tickets, walkthroughs, the Project Fair), which have make-up rules instead (<a href="#missed-studios-and-make-up-work">section 11</a>). Running out of free credits is not by itself a reason to be late, because switching to a fallback is part of the course. Full rules: <a href="./assessment/#late-work-and-grace-tokens">Late work and grace tokens</a>.</p><h3 id="passfail" tabindex="-1">Pass/fail <a class="header-anchor" href="#passfail" aria-label="Permalink to &quot;Pass/fail&quot;">​</a></h3><p>This course is letter-graded. If you&#39;re eligible, you may take it under the University&#39;s pass/fail option (catalog Regulation B-10-a). Talk with your advisor first. You need a cumulative GPA of 2.00 or higher (unless it&#39;s your first university-level term); you may take one such course a semester, and no more than 12 such credits count toward a bachelor&#39;s degree. The option isn&#39;t open for courses in your major or major subject field, courses your curriculum or college requires, or general-education courses. The deadline to switch is early in the term: see the Registrar&#39;s <a href="https://www.uidaho.edu/registrar/dates-deadlines" target="_blank" rel="noreferrer">dates and deadlines</a>. I&#39;m not told who chose it: I report a letter grade, and the Registrar records a C or higher as P. For undergraduates, a D stays a D (B-10-d).</p><h3 id="incompletes" tabindex="-1">Incompletes <a class="header-anchor" href="#incompletes" aria-label="Permalink to &quot;Incompletes&quot;">​</a></h3><p>Apart from the academic-integrity case in <a href="#academic-integrity">section 11</a> (FSH 2300 F-9), an Incomplete (I) is possible only under catalog Regulation F: you have been attending and doing passing work until near the end (the regulation&#39;s cutoff is three weeks before the close of the semester), and an extenuating circumstance, such as serious illness or a death in the family, makes it impossible to finish on time. We agree it together, I set out in writing what&#39;s left to do and by when, and I record a grade that applies if the work isn&#39;t completed. Running out of time because of procrastination doesn&#39;t qualify. You must finish by the Regulation F-2 deadline (the last day of the following summer for a fall Incomplete, the last day of the following fall semester for a spring or summer one); otherwise the I changes automatically to the grade I recorded. You can&#39;t graduate with an I on your record (F-3). If something serious happens, talk to me as early as you can.</p><h2 id="8-ai-use-policy" tabindex="-1">8. AI use policy <a class="header-anchor" href="#8-ai-use-policy" aria-label="Permalink to &quot;8. AI use policy&quot;">​</a></h2><p>This course <strong>requires</strong> AI. The rule is not &quot;how much AI did you use&quot; but &quot;can you explain what you shipped&quot;. Every task is labeled with one of three levels, always in words as well as color.</p><table tabindex="0"><thead><tr><th>Level</th><th>When</th><th>The complete list</th></tr></thead><tbody><tr><td>🟢 <strong>AI on</strong></td><td>Building, explaining, learning</td><td>Generating code; asking for explanations, plans and reviews of your diffs; debugging outside the Debug Clinic; translating instructions into your own language. Everything not listed below is 🟢 AI on</td></tr><tr><td>🟡 <strong>AI limited</strong></td><td>Where the goal is your own thinking</td><td><strong>Your <code>SPEC.md</code></strong> (Project 1 and capstone): the AI may ask questions, critique it and run the Goldfish test, but you write it. <strong>Your capstone pitch:</strong> critique only. <strong>The Debug Clinic</strong> (week 7): AI off, then hint-only <a href="./resources/tutor-mode.html">tutor mode</a> after 10 minutes stuck on one bug. <strong>&quot;You write it&quot;</strong> (week 8): the AI may plan and review, but you write the code. <strong>Any other task a brief marks 🟡 AI limited</strong> follows that brief</td></tr><tr><td>🔴 <strong>AI off</strong></td><td>Checks of your understanding, and writing addressed to people</td><td>Exit tickets · oral walkthroughs, retakes, skill follow-ups and &quot;explain it&quot; conversations · weekly and final reflections, including the week 6 bake-off Verdict · written peer reviews (an AI review may come <em>after</em> yours, to compare) · peer explanation swaps · the pre- and post-course self-assessments · your personal AI-use rules (week 2, revised in finals week) · your response to the AI fluency pre-work · the first draft of your Project 1 spec (week 5) · the hand-made code changes and the feature you write by hand in week 1 · the prompt-makeover rewrites (week 4) · the micro-app&#39;s &quot;Where the key lives and who can read it&quot; section (week 10) · the AI-off maintenance task (week 14) · the teach-back notes and the &quot;What I wrote or decided myself&quot; section of <code>PROMPTS.md</code> · a pair&#39;s contribution statement · any other task a brief marks 🔴 AI off</td></tr></tbody></table><p><strong>If two labels ever seem to disagree,</strong> follow the stricter one and ask. Using AI on 🔴 AI-off work, or beyond what a 🟡 AI-limited label allows, is academic dishonesty under the University&#39;s Student Code of Conduct (<a href="#academic-integrity">section 11</a>).</p><ul><li><strong>Disclose:</strong> every project has a <code>PROMPTS.md</code> with your key prompts, links to exported chats where possible, notes on what you changed, and teach-back notes for AI-written changes. Commits made with AI help end with an <code>Assisted-by: [tool]</code> line.</li><li><strong>Own it:</strong> &quot;If you can&#39;t explain it, you didn&#39;t build it.&quot; You may be asked to explain any line you submit.</li><li><strong>Credit others:</strong> if you use code, images or text from a person or website, credit it in your README. Using prompts you found online is fine; say where they came from.</li><li><strong>Your own rules:</strong> in week 2 you write a few personal rules for when you will and won&#39;t use AI, and in finals week you revise them. Students who set their own rules tend to do better (<a href="https://arxiv.org/abs/2609.16784" target="_blank" rel="noreferrer">Azimi</a>).</li></ul><h2 id="9-safety-and-privacy" tabindex="-1">9. Safety and privacy <a class="header-anchor" href="#9-safety-and-privacy" aria-label="Permalink to &quot;9. Safety and privacy&quot;">​</a></h2><h3 id="the-safety-contract" tabindex="-1">The safety contract <a class="header-anchor" href="#the-safety-contract" aria-label="Permalink to &quot;The safety contract&quot;">​</a></h3><p>Before Studio 1 you set your privacy settings and skim the <a href="./setup/safety-contract.html">safety contract</a>; you sign it on Canvas during week 1. Each rule starts the week it&#39;s taught, and the course sets up the protections around you (a Codespace sandbox, starters that keep keys off the browser, a secret scanner). In short:</p><table tabindex="0"><thead><tr><th>Rule</th><th>In plain words</th><th>Taught in</th></tr></thead><tbody><tr><td>1. Privacy settings first</td><td>Turn off &quot;train on my chats&quot; before you type anything</td><td>Weeks 0–1</td></tr><tr><td>2. I never paste secrets or other people&#39;s data into an AI tool</td><td>No keys, passwords, <code>.env</code> files or anyone else&#39;s personal information in a chat</td><td>Week 1; keys in week 9</td></tr><tr><td>3. I commit before and after every agent task</td><td>Git is your backup, not the agent&#39;s undo</td><td>Week 3; agents in week 11</td></tr><tr><td>4. I keep agents contained</td><td>Agents work in a sandbox with approvals on, the smallest keys possible, hard spending caps, and no reach to your backups</td><td>Week 9; agents in week 11</td></tr><tr><td>5. I verify, I don&#39;t trust</td><td>Check claims against real output; passing tests is not a security check, so test who can read and change your data yourself</td><td>Weeks 3–4 and 7; security in week 13</td></tr><tr><td>6. I check packages before I install them</td><td>Installing runs code: install only what the plan named, check it, and pin the version</td><td>Week 9; again in week 14</td></tr><tr><td>7. I read before I adopt</td><td>Read any rules file, skill, plugin, hook, MCP server or script first; never open a project folder someone sent you with an agent; clone it from its URL instead</td><td>Week 11</td></tr><tr><td>8. I keep a record of what I wrote myself</td><td><code>PROMPTS.md</code>, and an <code>Assisted-by:</code> line on AI-assisted commits</td><td>Weeks 2–3; required from week 11</td></tr><tr><td>9. Agents don&#39;t publish, and untrusted content never shares a session with my secrets</td><td>No agent makes anything public without your approval; an agent reading strangers&#39; content never has your keys within reach; no autopilot modes</td><td>Week 11; prompt injection in week 14</td></tr></tbody></table><h3 id="privacy-of-your-work" tabindex="-1">Privacy of your work <a class="header-anchor" href="#privacy-of-your-work" aria-label="Permalink to &quot;Privacy of your work&quot;">​</a></h3><p>Your projects are public on purpose: they become your portfolio. Your grades and personal writing are not. University policy treats grades and graded work as private (FSH 4700 F-6, and FSH 2600, which applies FERPA, the US federal student-records law), so:</p><ul><li><strong>In your public repos,</strong> under your GitHub username: code, <code>SPEC.md</code>, <code>TESTS.md</code>, <code>PROMPTS.md</code>, <code>AGENTS.md</code>, <code>SECURITY_CHECKLIST.md</code> and READMEs.</li><li><strong>On Canvas only:</strong> reflections, exit tickets, your personal AI-use rules, the signed safety contract, self-assessments, written peer reviews, pair contribution statements, the capstone pitch, and all grades and feedback.</li><li><strong>Never commit</strong> grades, feedback, reflections, classmates&#39; real names (use GitHub usernames), your student ID, or real personal data about anyone. You don&#39;t need your real name anywhere public.</li></ul><p>Details, including private repos and recordings: <a href="./assessment/#privacy-of-your-work">Privacy of your work</a>.</p><h2 id="10-tools-and-cost" tabindex="-1">10. Tools and cost <a class="header-anchor" href="#10-tools-and-cost" aria-label="Permalink to &quot;10. Tools and cost&quot;">​</a></h2><p>Required cost: <strong>$0</strong>. Every layer has a primary free tool and two fallbacks, listed in <a href="./TOOLS.html">Tool Handout</a>. If you choose to pay for one thing, the most useful options are the cheapest paid plan of the editor assistant, or one month of a frontier coding agent timed to the agent weeks, 11–16 (prices in TOOLS.md). Neither is needed to earn full marks.</p><p>Free tiers change without notice. When a tool stops working for you, the fallback is part of the course, not a failure: see <a href="./resources/troubleshooting.html#i-ran-out-of-free-credits">Troubleshooting: I ran out of free credits</a>. Never add a payment method to a free account just to keep going; ask first.</p><h2 id="11-course-policies" tabindex="-1">11. Course policies <a class="header-anchor" href="#11-course-policies" aria-label="Permalink to &quot;11. Course policies&quot;">​</a></h2><h3 id="attendance-and-participation" tabindex="-1">Attendance and participation <a class="header-anchor" href="#attendance-and-participation" aria-label="Permalink to &quot;Attendance and participation&quot;">​</a></h3><p>Studios are where most of the learning happens, and they count for <strong>15% of your grade</strong> (30 studios, two a week in weeks 1–15, each scored out of 10 for lab work, peer explanation, and the checkpoint or exit ticket; the Project Fair in finals week is scored the same way). Your <strong>lowest four of these scores are dropped</strong>, which covers a few ordinary missed days. Missing more than that lowers this component, and missing a walkthrough or the Project Fair affects those items too. You&#39;re responsible for catching up on what you missed: each week&#39;s lab is written step by step, and the studios&#39; project-work time and office hours are there for catch-up help.</p><h3 id="missed-studios-and-make-up-work" tabindex="-1">Missed studios and make-up work <a class="header-anchor" href="#missed-studios-and-make-up-work" aria-label="Permalink to &quot;Missed studios and make-up work&quot;">​</a></h3><ul><li><strong>Absences the University recognizes</strong> (catalog Regulation M-1): official university activities, your own illness, family illness or care, or other compelling circumstances. Tell me as soon as you can (before the absence, for official activities). You can make up the studio for <strong>full credit within one week</strong>: do the lab&#39;s core parts and, for the studio with that week&#39;s exit ticket, the exit ticket on Canvas. Missed walkthroughs are rescheduled without penalty.</li><li><strong>Religious observance</strong> (Regulation M-3): walkthroughs, exit tickets and the Project Fair are rescheduled. Tell me as early as you can.</li><li><strong>Other absences:</strong> do the lab and (for the studio with the exit ticket) the exit ticket within 48 hours for up to 7 of the 10 points.</li><li><strong>Online or in another time zone for part of the course?</strong> Talk to me in week 1, so we can set up the online arrangements.</li></ul><p>Full rules: <a href="./assessment/#absences-and-make-up-work">Absences and make-up work</a>. All three oral-walkthrough windows are posted on Canvas in week 1.</p><h3 id="recording-of-class-sessions" tabindex="-1">Recording of class sessions <a class="header-anchor" href="#recording-of-class-sessions" aria-label="Permalink to &quot;Recording of class sessions&quot;">​</a></h3><p>Students may record studios only with my consent or as an approved CDAR accommodation, and in either case must tell me first (FSH 4700 F-8). Concept talks I record are posted only on Canvas. Oral walkthroughs are recorded only with your consent, kept where only staff can see them, and deleted once grades are final.</p><h3 id="academic-integrity" tabindex="-1">Academic integrity <a class="header-anchor" href="#academic-integrity" aria-label="Permalink to &quot;Academic integrity&quot;">​</a></h3><p><strong>Disclosure is the rule.</strong> Honest disclosure of AI use in <code>PROMPTS.md</code> is never penalized, even when the AI did most of the typing.</p><p>The University of Idaho Student Code of Conduct and Resolution Process (FSH 2300) applies. In this course, academic dishonesty includes: using AI on 🔴 AI-off work or beyond a 🟡 AI-limited label (the Code names &quot;reliance on prohibited technological assistance/artificial intelligence tools&quot;, FSH 2300 E-1.c); fabricating evidence such as test results, security evidence or <code>PROMPTS.md</code> entries; submitting someone else&#39;s code, prompts or writing as your own; reusing work from another course without both instructors&#39; approval; and having someone else take your walkthrough or exit ticket.</p><p>There are two separate processes, and they never mix:</p><ol><li><strong>&quot;Explain it or redo it&quot; is a learning conversation, not a sanction.</strong> If you can&#39;t yet explain part of your own work, we talk for about 10 minutes. If you still can&#39;t, you redo that part within 7 days and it is graded on the normal rubric, with no penalty.</li><li><strong>Suspected academic dishonesty goes through the University&#39;s process.</strong> If I suspect it, I will tell you and report it to the Dean of Students, as FSH 2300 requires. <strong>No grade consequence is applied until that process has concluded</strong> and its decision has been communicated to you; if grades are due before then, an Incomplete is entered until it is resolved (FSH 2300 F-9). If the University&#39;s process finds you responsible, the most I can apply as an academic consequence is an F in the course (catalog Regulation O-2). The Dean of Students explains your options and rights.</li></ol><p>The course doesn&#39;t use AI detectors. Full details: <a href="./assessment/#academic-integrity">Academic integrity</a>.</p><h3 id="learning-civility" tabindex="-1">Learning civility <a class="header-anchor" href="#learning-civility" aria-label="Permalink to &quot;Learning civility&quot;">​</a></h3><p>In any environment in which people gather to learn, it is essential that all members feel as free and safe as possible in their participation. Everyone in this course is expected to be respectful and civil to one another in discussion, in action, in teaching and in learning. If our class interactions fall short of that, please talk with me; you can also contact the <a href="https://www.uidaho.edu/student-resources/dean-of-students" target="_blank" rel="noreferrer">Dean of Students</a> (208-885-6757), the <a href="https://www.uidaho.edu/student-resources/health-wellness/counseling-mental-health-center" target="_blank" rel="noreferrer">Counseling and Mental Health Center</a>&#39;s confidential services (208-885-6716), or the <a href="https://www.uidaho.edu/civil-rights" target="_blank" rel="noreferrer">Office of Civil Rights and Investigations</a> (208-885-4285). See also FSH 4170 (Maintaining Instructional Order).</p><h3 id="firearms" tabindex="-1">Firearms <a class="header-anchor" href="#firearms" aria-label="Permalink to &quot;Firearms&quot;">​</a></h3><p>The University of Idaho bans firearms from its property, with only limited exceptions (<a href="https://www.uidaho.edu/policies/apm/95/12" target="_blank" rel="noreferrer">University policy APM 95.12</a>). One exception lets holders of the licenses described in Idaho Code 18-3309(2), such as an Idaho enhanced concealed carry license, carry a firearm that stays concealed at all times; it doesn&#39;t apply in residence halls and some large venues. If you see a firearm on University property, or anyone who appears to be a danger, call 911.</p><h2 id="12-accessibility-and-support" tabindex="-1">12. Accessibility and support <a class="header-anchor" href="#12-accessibility-and-support" aria-label="Permalink to &quot;12. Accessibility and support&quot;">​</a></h2><h3 id="accessibility-and-accommodations" tabindex="-1">Accessibility and accommodations <a class="header-anchor" href="#accessibility-and-accommodations" aria-label="Permalink to &quot;Accessibility and accommodations&quot;">​</a></h3><p>The University of Idaho is committed to ensuring an accessible learning environment where course or instructional content are usable by all students and faculty. If you believe you require disability-related academic adjustments for this class (including pregnancy-related disabilities), please contact the <a href="https://www.uidaho.edu/student-resources/disability-accessibility-resources" target="_blank" rel="noreferrer">Center for Disability Access and Resources (CDAR)</a> to discuss eligibility. A current accommodation letter from CDAR is required before any modifications, above and beyond what is otherwise available for all other students in this class, will be provided. Disability-related academic adjustments are not retroactive. CDAR: Bruce M. Pitman Center, Suite 127; 208-885-6307; <a href="mailto:cdar@uidaho.edu" target="_blank" rel="noreferrer">cdar@uidaho.edu</a>; <a href="https://www.uidaho.edu/cdar" target="_blank" rel="noreferrer">services and hours</a>. CDAR also arranges adjustments for <a href="https://www.uidaho.edu/student-resources/disability-accessibility-resources/pregnancy-accommodations" target="_blank" rel="noreferrer">pregnancy and related conditions</a>.</p><p>Many adjustments are open to <strong>everyone</strong>, with or without a letter: typed answers, extra time or a written-first version for walkthroughs; untimed timed builds (they&#39;re graded on effort, not speed); a written script with screenshots instead of a demo video; large-print or screen-reader-friendly exit tickets (<a href="./assessment/#accommodations">full list</a>). The <a href="./resources/accessibility.html">accessibility guide</a> covers the course&#39;s tools with a screen reader or keyboard. Slides are plain text, every lab is written as step-by-step text, and Codespaces runs in a browser on modest laptops and Chromebooks. If a health condition, time zone, device or connectivity issue affects your work, tell me in week 1 so we can plan together.</p><h3 id="discrimination-harassment-and-sexual-misconduct" tabindex="-1">Discrimination, harassment and sexual misconduct <a class="header-anchor" href="#discrimination-harassment-and-sexual-misconduct" aria-label="Permalink to &quot;Discrimination, harassment and sexual misconduct&quot;">​</a></h3><p>As a U of I employee, I must report to the Office of Civil Rights and Investigations any information I receive about possible sex-based misconduct in a university program, so I can&#39;t keep it confidential (FSH 6100). For confidential support, contact the Counseling and Mental Health Center (208-885-6716). To report, or to learn your options, contact <a href="https://www.uidaho.edu/civil-rights" target="_blank" rel="noreferrer">OCRI</a>: <a href="mailto:ocri@uidaho.edu" target="_blank" rel="noreferrer">ocri@uidaho.edu</a>, 208-885-4285, 530 S Asbury St., Suite 5. In an emergency, call 911.</p><h3 id="your-well-being" tabindex="-1">Your well-being <a class="header-anchor" href="#your-well-being" aria-label="Permalink to &quot;Your well-being&quot;">​</a></h3><p>If stress, health, money, housing or anything else gets in the way, you don&#39;t have to handle it alone. The Counseling and Mental Health Center offers free counseling (208-885-6716; 24/7 crisis help: option 3). You can also ask the Dean of Students for support through <a href="https://www.uidaho.edu/student-resources/dean-of-students/vandalcare" target="_blank" rel="noreferrer">VandalCARE</a>, including a self-referral, or refer a classmate you&#39;re worried about. In an emergency, call 911.</p><h3 id="if-you-fall-behind" tabindex="-1">If you fall behind <a class="header-anchor" href="#if-you-fall-behind" aria-label="Permalink to &quot;If you fall behind&quot;">​</a></h3><p>Each week builds on the last, so act early:</p><ul><li>Do the <strong>Minimum to keep up</strong> box at the end of each week&#39;s homework first.</li><li>If Project 1 isn&#39;t working by week 7, a <strong>rescue starter</strong> (a small working app built from the course&#39;s example spec) lets you keep going: <a href="./projects/rescue-starters/">projects/rescue-starters/</a>.</li><li>Use the studios&#39; project-work time and office hours. &quot;I don&#39;t understand what the AI did&quot; is exactly what office hours are for.</li></ul><h3 id="student-resources" tabindex="-1">Student resources <a class="header-anchor" href="#student-resources" aria-label="Permalink to &quot;Student resources&quot;">​</a></h3><ul><li><strong>Technology help:</strong> the OIT <a href="https://www.uidaho.edu/student-resources/technical-support" target="_blank" rel="noreferrer">IT Service Desk</a> (TLC 128), 208-885-HELP (4357); requests at <a href="https://support.uidaho.edu/" target="_blank" rel="noreferrer">support.uidaho.edu</a>. For course tools, see <a href="./resources/troubleshooting.html">troubleshooting</a> first.</li><li><strong>Library:</strong> <a href="https://www.lib.uidaho.edu/" target="_blank" rel="noreferrer">lib.uidaho.edu</a></li><li><strong>Tutoring and study help:</strong> <a href="https://www.uidaho.edu/student-resources/academic-support/tutoring" target="_blank" rel="noreferrer">Vandals Tutoring</a> (drop-in), <a href="https://www.uidaho.edu/student-resources/academic-support/peer-assisted-study-sessions" target="_blank" rel="noreferrer">SI-PASS</a> (peer-led study sessions), the <a href="https://www.uidaho.edu/student-resources/academic-support/writing-center" target="_blank" rel="noreferrer">Writing Center</a>, Academic Coaching and the Computer Science Assistance Center (<a href="https://www.uidaho.edu/student-resources/academic-support" target="_blank" rel="noreferrer">all academic support</a>)</li><li><strong>Dean of Students:</strong> <a href="https://www.uidaho.edu/student-resources/dean-of-students" target="_blank" rel="noreferrer">support, advocacy and student conduct</a>, TLC 232, 208-885-6757</li><li><strong>Counseling and Mental Health Center:</strong> <a href="https://www.uidaho.edu/student-resources/health-wellness/counseling-mental-health-center" target="_blank" rel="noreferrer">free counseling</a> for any student enrolled for at least one credit; Mary Forney Hall, 3rd floor; 208-885-6716 (24/7 crisis help: option 3)</li><li><strong>Vandal Food Pantry:</strong> <a href="https://www.uidaho.edu/student-resources/dean-of-students/basic-needs-food-insecurity-resources" target="_blank" rel="noreferrer">free food for any student</a>, Shoup Hall 105; the Dean of Students also offers emergency meal swipes and basic-needs kits</li><li><strong>Green Dot:</strong> the University&#39;s <a href="https://www.uidaho.edu/student-resources/health-wellness/violence-prevention-center" target="_blank" rel="noreferrer">violence-prevention program</a></li></ul><h2 id="13-why-the-course-looks-like-this" tabindex="-1">13. Why the course looks like this <a class="header-anchor" href="#13-why-the-course-looks-like-this" aria-label="Permalink to &quot;13. Why the course looks like this&quot;">​</a></h2><p>The design is based on a review of 2025–26 university and industry courses, education research, security incidents, and the free-tool landscape, updated in October 2026. In November 2026 the course moved from eight accelerated weeks to a 16-week semester and gained a one-course programming prerequisite, and CS students who have completed CS 3383 got their own upper-division course, Engineering Software with AI. Short version: <a href="./research/design-rationale.html">Why the Course Looks Like This</a>. Full reports: <a href="./research/landscape-report-2026-09.html">Teach the Loop, Not the Tool</a> and the <a href="./research/landscape-update-2026-10.html">October 2026 update</a>.</p>',131)])])}const g=t(r,[["render",n]]);export{p as __pageData,g as default};
